IF (result->>'servingGrams')::numeric IS DISTINCT FROM (e#>>'{snapshot,serving_quantity}')::numeric THEN RAISE EXCEPTION 'mass_changed'; END IF;
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'nutrients') x WHERE x->>'provider_key'='carbohydrates_100g' AND x->>'status'='valid' AND (x->>'amount')::numeric=(e#>>'{snapshot,nutriments,carbohydrates_100g}')::numeric) THEN RAISE EXCEPTION 'canonical_changed'; END IF;
